import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import {eventOccursOn,keyAt,localInputAt,wallTimeToUtc,isValidEventRange} from './domain.js';

const cfg = window.DEVVERSE_CONFIG || {};
const ready = Boolean(cfg.supabaseUrl && cfg.supabasePublishableKey);
const db = ready ? createClient(cfg.supabaseUrl, cfg.supabasePublishableKey, { auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true } }) : null;
const app = document.querySelector('#app');
const today = new Date();
const dateKey = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const zone = () => state.profile?.timezone || 'Asia/Kolkata';
function fmtAt(d,options,tz=zone()){return new Intl.DateTimeFormat(undefined,{...options,timeZone:tz}).format(d);}
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (name,size=18) => {
  const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',layers:'<path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 16l9 5 9-5"/>',check:'<path d="m5 12 4 4L19 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',note:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',brief:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18M10 12v2h4v-2"/>',chart:'<path d="M3 3v18h18"/><path d="m19 9-5 5-4-4-5 5"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.6a8 8 0 0 1-1.5.9l-.3 1.8h-2.8l-.3-1.8a8 8 0 0 1-1.5-.9l-1.7.6-1.4-2.4 1.4-1.1A7 7 0 0 1 7.6 13l-1.7-.9 1-2.6 1.9.3a8 8 0 0 1 1.2-1.2l-.3-1.9 2.7-1 .9 1.7a8 8 0 0 1 1.7 0l.9-1.7 2.7 1-.3 1.9a8 8 0 0 1 1.2 1.2l1.9-.3 1 2.6-1.7.9a7 7 0 0 1-.7 2Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',chevron:'<path d="m9 18 6-6-6-6"/>',moon:'<path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',logout:'<path d="M10 17l5-5-5-5M15 12H3"/><path d="M12 3h6a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-6"/>',close:'<path d="m18 6-12 12M6 6l12 12"/>',edit:'<path d="m15 5 4 4M4 20l4-.8L19 8a2.8 2.8 0 0 0-4-4L4 15Z"/>',trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6m4 4v7m6-7v7"/>',arrow:'<path d="M7 17 17 7M7 7h10v10"/>'};
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.grid}</svg>`;
};

const state={user:null,profile:null,page:'Overview',projects:[],tasks:[],events:[],notes:[],portfolio:[],month:new Date(today.getFullYear(),today.getMonth(),1),authMode:'signin',filter:'',loading:false,dataUserId:null};
const nav=[['Overview','grid'],['Projects','layers'],['Tasks','check'],['Calendar','calendar'],['Notes','note'],['Portfolio','brief'],['Analytics','chart']];

function toast(message,type='ok') { document.querySelector('.toast')?.remove(); const el=document.createElement('div'); el.className=`toast ${type}`; el.textContent=message; document.body.append(el); setTimeout(()=>el.remove(),3300); }
function field(label,name,value='',type='text',attrs=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}/></label>`;}
function textarea(label,name,value=''){return `<label class="field"><span>${label}</span><textarea name="${name}" rows="4">${esc(value)}</textarea></label>`;}
function selectField(label,name,value,options){return `<label class="field"><span>${label}</span><select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function modal(title,body,action='Save'){return `<div class="overlay" id="modal"><form class="modal" id="modal-form"><div class="modal-head"><div><p class="eyebrow">DEVVERSE STUDIO</p><h2>${title}</h2></div><button type="button" class="icon-btn" data-close aria-label="Close">${icon('close')}</button></div><div class="modal-body">${body}</div><div class="modal-actions"><button type="button" class="btn ghost" data-close>Cancel</button><button class="btn primary" type="submit">${action}</button></div></form></div>`;}

function showLanding(){app.innerHTML=`<main class="landing"><header class="landing-nav"><a class="brand" href="/">${mark()}<span>DEVVERSE<span class="brand-light"> STUDIO</span></span></a><nav aria-label="Main"><a href="#features">Features</a><a href="/privacy.html">Privacy</a><a href="/terms.html">Terms</a><button class="btn ghost" id="landing-signin">Sign in</button><button class="btn primary" id="landing-join">Get started ${icon('arrow',15)}</button></nav></header><section class="landing-hero"><div class="landing-copy"><span class="pill"><i></i> YOUR NEXT IDEA STARTS HERE</span><h1>Build better.<br/><em>Plan smarter.</em></h1><p>One focused workspace for projects, tasks, notes, and the moments you want to make time for.</p><div class="landing-actions"><button class="btn primary" id="landing-join-hero">Start building ${icon('arrow',16)}</button><a class="landing-text-link" href="#features">See what’s inside ↓</a></div><div class="landing-note"><span class="landing-check">✓</span><span>Private by default <i>·</i> Your ideas stay yours</span></div></div><div class="landing-preview"><div class="preview-glow"></div><div class="preview-window"><div class="preview-side"><div class="preview-brand">${mark(19)} <b>DEVVERSE</b></div><span class="preview-active">▦ &nbsp; Overview</span><span>◇ &nbsp; Projects</span><span>✓ &nbsp; Tasks</span><span>▤ &nbsp; Calendar</span><span>▧ &nbsp; Notes</span></div><div class="preview-main"><div class="preview-top"><small>Workspace &nbsp; / &nbsp; Your overview</small><i>D</i></div><div class="preview-welcome"><small>MONDAY · YOUR WORKSPACE</small><b>Make room for<br/>big ideas.</b><span>Turn your next step into forward motion.</span><button>＋ Create something</button></div><div class="preview-metrics"><div><small>ACTIVE PROJECTS</small><b>—</b></div><div><small>TASKS THIS WEEK</small><b>—</b></div><div><small>YOUR NOTES</small><b>—</b></div></div><div class="preview-panels"><div><small>STAY IN FLOW</small><b>Tasks on your plate</b><span>Start with one clear next step.</span></div><div><small>MAKE TIME FOR IT</small><b>Coming up</b><span>Your calendar, your rhythm.</span></div></div></div></div><div class="preview-float">${icon('check',17)} <span><b>One calm workspace</b><small>For everything you’re making</small></span></div></div></section><section class="landing-features" id="features"><div class="landing-section-head"><p class="eyebrow">MADE FOR YOUR WAY OF WORKING</p><h2>Everything you need to<br/><em>keep moving.</em></h2><p>Make the plan. Keep the details close. Get back to creating.</p></div><div class="feature-grid"><article class="feature-card"><span>${icon('layers',21)}</span><h3>Projects that stay clear</h3><p>Keep goals, deadlines, and tasks connected in one focused view.</p></article><article class="feature-card"><span>${icon('calendar',21)}</span><h3>A calendar that’s yours</h3><p>Plan the work and the life around it, in your own timezone.</p></article><article class="feature-card"><span>${icon('note',21)}</span><h3>Room for every thought</h3><p>Capture notes, shape ideas, and connect them to the work they inspire.</p></article><article class="feature-card"><span>${icon('brief',21)}</span><h3>Share work on your terms</h3><p>Your portfolio stays private until you choose to publish an item.</p></article></div></section><section class="landing-close"><span class="eyebrow">YOUR NEXT CHAPTER</span><h2>Good things happen<br/>when you <em>make a plan.</em></h2><button class="btn white" id="landing-join-bottom">Create your workspace ${icon('arrow',16)}</button></section><footer class="landing-footer"><a class="brand" href="/">${mark(22)}<span>DEVVERSE<span class="brand-light"> STUDIO</span></span></a><span>Build Better. Plan Smarter. Create Without Limits.</span><div><a href="/privacy.html">Privacy</a><a href="/terms.html">Terms</a></div></footer></main>`;for(const id of ['landing-join','landing-join-hero','landing-join-bottom'])document.querySelector('#'+id).onclick=()=>{state.authMode='signup';showAuth();};document.querySelector('#landing-signin').onclick=()=>{state.authMode='signin';showAuth();};}

function showAuth(){const mode=state.authMode,recover=mode==='recover-password',reset=mode==='reset';app.innerHTML=`<main class="auth-page"><section class="auth-art"><a class="brand" href="/">${mark()}<span>DEVVERSE<span class="brand-light"> STUDIO</span></span></a><div class="auth-copy"><span class="pill"><i></i> YOUR CREATIVE HQ</span><h1>Make space<br/>for <em>big ideas.</em></h1><p>One focused workspace for everything you want to build.</p><div class="auth-orbit"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit-core">${mark(58)}</div><span class="orbit-tag tag-a">Projects</span><span class="orbit-tag tag-b">Your rhythm</span><span class="orbit-tag tag-c">Ideas</span></div></div><div class="auth-foot">BUILD BETTER. PLAN SMARTER. CREATE WITHOUT LIMITS.</div></section><section class="auth-panel"><div class="auth-box"><p class="eyebrow">WELCOME TO YOUR WORKSPACE</p><h2>${reset?'Reset your password':recover?'Choose a new password':mode==='signin'?'Welcome back':'Start building'}</h2><p class="muted">${reset?'We’ll email you a secure password reset link.':recover?'Choose a new password for your account.':mode==='signin'?'Sign in to pick up where you left off.':'Create your workspace account.'}</p><form id="auth-form">${mode==='signup'?field('Your name','display_name','','text','autocomplete="name" required'):''}${!recover?field('Email address','email','','email','autocomplete="email" required'):''}${!reset?field(recover?'New password':'Password','password','','password',`autocomplete="${mode==='signin'?'current-password':'new-password'}" minlength="8" required`):''}<button class="btn primary full" type="submit">${reset?'Send reset link':recover?'Update password':mode==='signin'?'Sign in':'Create account'} <span>${icon('arrow')}</span></button></form><p class="auth-switch">${mode==='signin'?"New to Devverse?":"Already have an account?"} <button class="text-btn" id="auth-switch">${mode==='signin'?'Create an account':'Sign in'}</button>${mode==='signin'?'<br/><button class="text-btn" id="forgot-password">Forgot password?</button>':''}</p><p class="auth-legal">Please read our <a href="/privacy.html">Privacy Notice</a> and <a href="/terms.html">Terms of Use</a>.</p></div></section></main>`;
  document.querySelector('#auth-switch').onclick=()=>{state.authMode=mode==='signin'?'signup':'signin';showAuth();};document.querySelector('#forgot-password')?.addEventListener('click',()=>{state.authMode='reset';showAuth();});
  document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();if(!db)return;const form=Object.fromEntries(new FormData(e.currentTarget)),button=e.currentTarget.querySelector('button');button.disabled=true;button.textContent='Please wait…';try{if(mode==='signup'){const {error}=await db.auth.signUp({email:form.email,password:form.password,options:{data:{display_name:form.display_name},emailRedirectTo:location.origin}});if(error)throw error;toast('Check your email to confirm your account.');}else if(reset){const {error}=await db.auth.resetPasswordForEmail(form.email,{redirectTo:`${location.origin}/?recovery=1`});if(error)throw error;toast('If that address has an account, a reset link is on its way.');state.authMode='signin';showAuth();}else if(recover){const {error}=await db.auth.updateUser({password:form.password});if(error)throw error;history.replaceState({},'',location.pathname);state.authMode='signin';toast('Password updated. Sign in with your new password.');showAuth();}else{const {error}=await db.auth.signInWithPassword({email:form.email,password:form.password});if(error)throw error;}}catch(err){toast(err.message||'Authentication failed','error');button.disabled=false;button.textContent=reset?'Send reset link':recover?'Update password':mode==='signin'?'Sign in':'Create account';}};
}
function mark(size=28){return `<svg width="${size}" height="${size}" viewBox="0 0 40 40" fill="none"><rect width="40" height="40" rx="12" fill="url(#logo-grad)"/><path d="M9 10h13a10 10 0 1 1 0 20H9V10Zm7 7v6h6a3 3 0 1 0 0-6h-6Z" fill="white"/><circle cx="30" cy="10" r="2.3" fill="#D9CEFF"/><defs><linearGradient id="logo-grad" x1="5" y1="4" x2="37" y2="38"><stop stop-color="#9E8CFF"/><stop offset="1" stop-color="#5A7AF8"/></linearGradient></defs></svg>`;}

function clearWorkspaceData(){state.projects=[];state.tasks=[];state.events=[];state.notes=[];state.portfolio=[];state.profile=null;state.dataUserId=null;}
async function loadData(){if(!db||!state.user)return;const requestedUser=state.user.id;if(state.dataUserId!==requestedUser){clearWorkspaceData();state.dataUserId=requestedUser;}state.loading=true;try{const queries=['projects','tasks','events','notes','portfolio_items'].map(t=>db.from(t).select('*').order('updated_at',{ascending:false}).limit(250));const [p,t,e,n,port]=await Promise.all(queries);for(const r of [p,t,e,n,port])if(r.error)throw r.error;const prof=await db.from('profiles').select('*').eq('id',requestedUser).maybeSingle();if(prof.error)throw prof.error;if(state.user?.id!==requestedUser)return;state.projects=p.data||[];state.tasks=t.data||[];state.events=e.data||[];state.notes=n.data||[];state.portfolio=port.data||[];state.profile=prof.data||{display_name:state.user.user_metadata?.display_name||'',theme:'dark',timezone:'Asia/Kolkata'};document.documentElement.dataset.theme=state.profile.theme||'dark';}catch(err){if(state.user?.id!==requestedUser)return;clearWorkspaceData();state.dataUserId=requestedUser;state.profile={display_name:state.user.user_metadata?.display_name||'',theme:'dark',timezone:'Asia/Kolkata'};toast('Could not load workspace: '+err.message,'error');}finally{if(state.user?.id===requestedUser){state.loading=false;render();}}}
async function save(table,payload,id){const q=id?db.from(table).update(payload).eq('id',id).select().single():db.from(table).insert({...payload,user_id:state.user.id}).select().single();const {data,error}=await q;if(error)throw error;await loadData();return data;}
async function remove(table,id,label){if(!confirm(`Delete this ${label}? This cannot be undone.`))return;try{const {error}=await db.from(table).delete().eq('id',id);if(error)throw error;await loadData();toast(`${label[0].toUpperCase()+label.slice(1)} deleted.`);}catch(err){toast(err.message,'error');}}
function render(){if(!state.user){showLanding();return;}const titles={Overview:'Your overview',Projects:'Projects',Tasks:'Tasks',Calendar:'Calendar',Notes:'Notes',Portfolio:'Portfolio',Analytics:'Analytics',Settings:'Settings'};app.innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="#overview">${mark()}<span>DEVVERSE<span class="brand-light"> STUDIO</span></span></a><div class="side-label">WORKSPACE</div><nav class="side-nav">${nav.map(([n,ic])=>`<button class="nav-item ${state.page===n?'active':''}" data-page="${n}">${icon(ic)}<span>${n}</span>${n==='Tasks'&&state.tasks.filter(t=>t.status!=='done').length?`<b class="nav-count">${state.tasks.filter(t=>t.status!=='done').length}</b>`:''}</button>`).join('')}</nav><div class="side-label side-label-bottom">PREFERENCES</div><button class="nav-item ${state.page==='Settings'?'active':''}" data-page="Settings">${icon('settings')}<span>Settings</span></button><div class="sidebar-bottom"><div class="workspace-card"><div class="workspace-mark">DS</div><div><strong>${esc(state.profile?.display_name||state.user.email?.split('@')[0]||'Your workspace')}</strong><small>Personal workspace</small></div><button class="mini-icon" id="signout" title="Sign out">${icon('logout',16)}</button></div><div class="sidebar-tag">${mark(18)}<span>BUILD SOMETHING<br/>THAT MATTERS</span></div></div></aside><main class="main-area"><header class="topbar"><button id="mobile-menu" class="icon-btn menu-toggle" aria-label="Open menu">☰</button><div class="crumb">Workspace <span>/</span> <b>${titles[state.page]||state.page}</b></div><div class="top-actions"><label class="global-search">${icon('search',16)}<input id="global-search" placeholder="Search your workspace" value="${esc(state.filter)}"/><kbd>⌘ K</kbd></label><button class="icon-btn theme-toggle" id="theme-toggle" aria-label="Toggle theme">${icon(document.documentElement.dataset.theme==='light'?'moon':'sun')}</button><button class="avatar" data-page="Settings">${esc((state.profile?.display_name||state.user.email||'D')[0].toUpperCase())}</button></div></header><div class="page-content">${pageContent()}</div></main></div><div id="modal-root"></div>`;
  document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.filter='';render();});document.querySelector('#signout').onclick=async()=>{await db.auth.signOut();state.user=null;clearWorkspaceData();showLanding();};document.querySelector('#theme-toggle').onclick=toggleTheme;document.querySelector('#global-search').oninput=e=>{state.filter=e.target.value;render();const input=document.querySelector('#global-search');input.focus();input.setSelectionRange(input.value.length,input.value.length);};document.querySelector('#mobile-menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');document.querySelectorAll('[data-create]').forEach(b=>b.onclick=()=>createModal(b.dataset.create));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editModal(b.dataset.edit,b.dataset.id));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>remove(b.dataset.table,b.dataset.id,b.dataset.delete));document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>toggleTask(b.dataset.id));document.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{state.month.setMonth(state.month.getMonth()+Number(b.dataset.month));render();});document.querySelectorAll('[data-event-date]').forEach(b=>b.onclick=()=>createModal('event',b.dataset.eventDate));document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>editModal('note',b.dataset.id));document.querySelector('#new-action')?.addEventListener('click',()=>createModal(state.page==='Overview'?'task':state.page==='Calendar'?'event':state.page==='Notes'?'note':state.page==='Projects'?'project':state.page==='Portfolio'?'portfolio':'task'));document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);document.querySelector('#modal-form')?.addEventListener('submit',submitModal);document.querySelector('#project-filter')?.addEventListener('change',e=>{state.projectStatus=e.target.value;render();});document.querySelector('#task-status-filter')?.addEventListener('change',e=>{state.taskStatus=e.target.value;render();});
}
function pageContent(){const name=esc(state.profile?.display_name||state.user.email?.split('@')[0]||'there');if(state.page==='Overview')return dashboard(name);if(state.page==='Projects')return projectPage();if(state.page==='Tasks')return taskPage();if(state.page==='Calendar')return calendarPage();if(state.page==='Notes')return notesPage();if(state.page==='Portfolio')return portfolioPage();if(state.page==='Analytics')return analyticsPage();return settingsPage();}
function pageHeading(eyebrow,title,desc,button='Create new'){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="muted">${desc}</p></div><button class="btn primary" id="new-action">${icon('plus',17)} ${button}</button></div>`;}
function greeting(){const h=new Date().getHours();return h<12?'Good morning':h<18?'Good afternoon':'Good evening';}
function dashboard(name){const active=state.projects.filter(p=>p.status==='active').length,due=state.tasks.filter(t=>t.status!=='done'&&t.due_date&&t.due_date<=dateKey(new Date(Date.now()+7*86400000))).length,done=state.tasks.filter(t=>t.status==='done').length,upcoming=state.events.filter(e=>new Date(e.end_at)>=new Date()).sort((a,b)=>new Date(a.start_at)-new Date(b.start_at)).slice(0,3);const tasks=state.tasks.filter(t=>t.status!=='done').sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')).slice(0,4);return `<section class="welcome-banner"><div><p class="eyebrow">${greeting().toUpperCase()} · ${today.toLocaleDateString('en-IN',{weekday:'long',month:'long',day:'numeric'})}</p><h1>Good things happen<br/>when you <em>make a plan.</em></h1><p>Your ideas deserve a workspace that moves as fast as you do.</p><button class="btn white" id="new-action">${icon('plus',17)} Create something</button></div><div class="welcome-art"><div class="art-orb orb-1"></div><div class="art-orb orb-2"></div><div class="art-card card-float"><span class="art-icon">${icon('check',22)}</span><div><b>Progress, your way</b><small>One focused step at a time</small></div></div><span class="sparkle">✳</span></div></section><div class="stat-grid"><article class="stat-card"><span class="stat-icon violet">${icon('layers')}</span><span class="stat-label">Active projects</span><strong>${active}</strong><small>${state.projects.length?`${state.projects.length} in your workspace`:'Start with one idea'}</small></article><article class="stat-card"><span class="stat-icon blue">${icon('calendar')}</span><span class="stat-label">Due this week</span><strong>${due}</strong><small>${due?'Keep your momentum':'A little breathing room'}</small></article><article class="stat-card"><span class="stat-icon green">${icon('check')}</span><span class="stat-label">Tasks completed</span><strong>${done}</strong><small>${done?'Look at you go':'Every journey starts somewhere'}</small></article><article class="stat-card"><span class="stat-icon amber">${icon('note')}</span><span class="stat-label">Your notes</span><strong>${state.notes.length}</strong><small>${state.notes.length?'Ideas worth keeping':'A space for your thinking'}</small></article></div><div class="content-grid"><section class="panel"><div class="panel-heading"><div><p class="eyebrow">STAY IN FLOW</p><h2>Tasks on your plate</h2></div><button class="link-btn" data-page="Tasks">View all ${icon('chevron',15)}</button></div>${tasks.length?`<div class="task-list">${tasks.map(t=>taskRow(t)).join('')}</div>`:empty('Nothing on your list yet','Add a task and give your next idea a first step.')}</section><section class="panel"><div class="panel-heading"><div><p class="eyebrow">MAKE ROOM FOR IT</p><h2>Coming up</h2></div><button class="link-btn" data-page="Calendar">Calendar ${icon('chevron',15)}</button></div>${upcoming.length?`<div class="upcoming-list">${upcoming.map(e=>`<div class="upcoming-row"><div class="date-chip"><b>${fmtAt(new Date(e.start_at),{day:'2-digit'})}</b><small>${fmtAt(new Date(e.start_at),{month:'short'}).toUpperCase()}</small></div><div><strong>${esc(e.title)}</strong><small>${e.all_day?'All day':fmtAt(new Date(e.start_at),{hour:'2-digit',minute:'2-digit'})} · ${esc(e.description||'Event')}</small></div><i style="--event:${e.color}"></i></div>`).join('')}</div>`:empty('Nothing scheduled yet','Your upcoming events will find a home here.')}</section></div><div class="content-grid bottom-grid"><section class="panel"><div class="panel-heading"><div><p class="eyebrow">YOUR FOCUS</p><h2>Projects in motion</h2></div><button class="link-btn" data-page="Projects">All projects ${icon('chevron',15)}</button></div>${state.projects.length?`<div class="project-mini-list">${state.projects.slice(0,4).map(projectMini).join('')}</div>`:empty('A blank canvas','Create a project to bring your plans together.')}</section><section class="quote-panel"><span class="quote-mark">“</span><p>Your best work happens when your head is clear and your next step is obvious.</p><span>MAKE SPACE TO CREATE</span><div class="quote-lines"></div></section></div>`;}
function empty(title,copy){return `<div class="empty-state"><div class="empty-glyph">${mark(34)}</div><strong>${title}</strong><p>${copy}</p></div>`;}
function taskRow(t){return `<div class="task-row"><button class="check-button ${t.status==='done'?'checked':''}" data-toggle="${t.id}" aria-label="${t.status==='done'?'Reopen':'Complete'} task">${t.status==='done'?icon('check',14):''}</button><div class="task-main"><strong class="${t.status==='done'?'strike':''}">${esc(t.title)}</strong><small>${esc(state.projects.find(p=>p.id===t.project_id)?.name||'Personal task')}${t.due_date?` · ${new Date(t.due_date+'T12:00:00').toLocaleDateString('en-IN',{month:'short',day:'numeric'})}`:''}</small></div><span class="priority ${t.priority}">${t.priority}</span><button class="mini-icon row-edit" data-edit="task" data-id="${t.id}" aria-label="Edit task">${icon('edit',15)}</button></div>`;}
function projectMini(p){let all=state.tasks.filter(t=>t.project_id===p.id),done=all.filter(t=>t.status==='done').length,pct=all.length?Math.round(done/all.length*100):0;return `<div class="project-mini"><div class="project-dot" style="--project:${p.color}"></div><div class="project-mini-main"><div><strong>${esc(p.name)}</strong><small>${all.length?`${done} of ${all.length} tasks`:'No tasks yet'}</small></div><div class="progress-track"><i style="width:${pct}%;--project:${p.color}"></i></div></div><span class="progress-pct">${pct}%</span></div>`;}
function projectPage(){let list=state.projects.filter(p=>`${p.name} ${p.description}`.toLowerCase().includes(state.filter.toLowerCase())&&(state.projectStatus==='all'||p.status===state.projectStatus));return `${pageHeading('YOUR WORK, IN MOTION','Projects','Keep the big picture close while you move the small pieces forward.')}<div class="toolbar"><span class="result-count">${list.length} project${list.length===1?'':'s'}</span><div class="toolbar-right"><select id="project-filter" class="filter-select"><option value="all" ${!state.projectStatus||state.projectStatus==='all'?'selected':''}>All projects</option><option value="active" ${state.projectStatus==='active'?'selected':''}>In progress</option><option value="completed" ${state.projectStatus==='completed'?'selected':''}>Completed</option></select></div></div>${list.length?`<div class="project-grid">${list.map(p=>{let tasks=state.tasks.filter(t=>t.project_id===p.id),done=tasks.filter(t=>t.status==='done').length,pct=tasks.length?Math.round(done/tasks.length*100):0;return `<article class="project-card"><div class="project-cover" style="--project:${p.color}"><span class="project-status">${p.status.replace('_',' ')}</span><div class="cover-shape"></div><div class="cover-mark">${mark(32)}</div></div><div class="project-card-body"><div class="project-card-title"><h3>${esc(p.name)}</h3><button class="mini-icon" data-edit="project" data-id="${p.id}" aria-label="Edit project">${icon('edit',15)}</button></div><p>${esc(p.description||'A place to make this idea happen.')}</p><div class="project-card-meta"><span>${tasks.length} tasks</span>${p.deadline?`<span>Due ${new Date(p.deadline+'T12:00:00').toLocaleDateString('en-IN',{month:'short',day:'numeric'})}</span>`:''}</div><div class="progress-track"><i style="width:${pct}%;--project:${p.color}"></i></div><div class="project-card-foot"><small>${pct}% complete</small><button class="text-btn danger-text" data-delete="project" data-table="projects" data-id="${p.id}">Delete</button></div></div></article>`}).join('')}</div>`:empty('Your first project starts here','Bring a goal, a side project, or a curiosity. We’ll help keep it moving.')}`;}
function taskPage(){const filtered=state.tasks.filter(t=>`${t.title} ${t.description}`.toLowerCase().includes(state.filter.toLowerCase()));return `${pageHeading('SMALL STEPS, REAL PROGRESS','Tasks','A clear next step can change the whole day.')}<div class="toolbar"><span class="result-count">${filtered.length} task${filtered.length===1?'':'s'}</span><div class="toolbar-right"><select class="filter-select" id="task-status-filter"><option value="all" ${!state.taskStatus||state.taskStatus==='all'?'selected':''}>Every status</option><option value="todo" ${state.taskStatus==='todo'?'selected':''}>To do</option><option value="in_progress" ${state.taskStatus==='in_progress'?'selected':''}>In progress</option><option value="done" ${state.taskStatus==='done'?'selected':''}>Completed</option></select></div></div><section class="panel task-panel">${filtered.length?`<div class="task-list roomy">${filtered.map(t=>taskRow(t)).join('')}</div>`:empty('A little space to think','Create a task when you’re ready to take the next step.')}</section>`;}
function calendarPage(){const m=state.month,y=m.getFullYear(),monthName=m.toLocaleDateString('en-IN',{month:'long',year:'numeric'}),start=new Date(y,m.getMonth(),1),offset=(start.getDay()+6)%7,days=new Date(y,m.getMonth()+1,0).getDate(),prevDays=new Date(y,m.getMonth(),0).getDate();let cells=[];for(let i=0;i<42;i++){let d=i-offset+1,date,other=false;if(d<1){date=new Date(y,m.getMonth()-1,prevDays+d);other=true;}else if(d>days){date=new Date(y,m.getMonth()+1,d-days);other=true;}else date=new Date(y,m.getMonth(),d);let key=dateKey(date),events=state.events.filter(e=>eventOccursOn(e,key,zone()));cells.push(`<button class="calendar-day ${other?'outside':''} ${key===keyAt(today,zone())?'is-today':''}" data-event-date="${key}"><span class="day-number">${date.getDate()}</span><span class="day-events">${events.slice(0,2).map(e=>`<i style="--event:${e.color}">${esc(e.title)}</i>`).join('')}${events.length>2?`<small>+${events.length-2} more</small>`:''}</span></button>`);}let future=state.events.filter(e=>new Date(e.end_at)>=new Date()).sort((a,b)=>new Date(a.start_at)-new Date(b.start_at)).slice(0,5);return `${pageHeading('MAKE TIME FOR WHAT MATTERS','Your calendar','A little breathing room can be the most productive thing.','Add event')}<section class="panel calendar-panel"><div class="calendar-toolbar"><div class="month-nav"><button class="icon-btn" data-month="-1" aria-label="Previous month">‹</button><h2>${monthName}</h2><button class="icon-btn" data-month="1" aria-label="Next month">›</button><button class="btn subtle" id="today-btn">Today</button></div><span class="calendar-zone">${esc(state.profile?.timezone||'Asia/Kolkata')}</span></div><div class="calendar-grid"><div class="weekday">MON</div><div class="weekday">TUE</div><div class="weekday">WED</div><div class="weekday">THU</div><div class="weekday">FRI</div><div class="weekday">SAT</div><div class="weekday">SUN</div>${cells.join('')}</div></section><section class="panel upcoming-panel"><div class="panel-heading"><div><p class="eyebrow">YOUR NEXT CHAPTER</p><h2>Upcoming events</h2></div></div>${future.length?`<div class="upcoming-list">${future.map(e=>`<div class="upcoming-row"><div class="date-chip"><b>${fmtAt(new Date(e.start_at),{day:'2-digit'})}</b><small>${fmtAt(new Date(e.start_at),{month:'short'}).toUpperCase()}</small></div><div><strong>${esc(e.title)}</strong><small>${e.all_day?'All day':fmtAt(new Date(e.start_at),{weekday:'short',hour:'2-digit',minute:'2-digit'})}${e.description?` · ${esc(e.description)}`:''}</small></div><div class="row-actions"><button class="mini-icon" data-edit="event" data-id="${e.id}">${icon('edit',15)}</button><button class="mini-icon" data-delete="event" data-table="events" data-id="${e.id}">${icon('trash',15)}</button></div></div>`).join('')}</div>`:empty('Your calendar is open','Add a moment worth making time for.')}</section>`;}
function notesPage(){let items=state.notes.filter(n=>`${n.title} ${n.body}`.toLowerCase().includes(state.filter.toLowerCase()));return `${pageHeading('THOUGHTS, SAFELY KEPT','Notes','Capture the thought before it turns into a to-do.','New note')}<div class="note-grid">${items.length?items.map(n=>`<article class="note-card" data-note="1" data-id="${n.id}"><div class="note-card-top"><span class="note-swatch"></span><div class="row-actions"><button class="mini-icon" data-edit="note" data-id="${n.id}" aria-label="Edit note">${icon('edit',15)}</button><button class="mini-icon" data-delete="note" data-table="notes" data-id="${n.id}" aria-label="Delete note">${icon('trash',15)}</button></div></div><h3>${esc(n.title||'Untitled note')}</h3><p>${esc(n.body||'Nothing written yet.')}</p><small>UPDATED ${new Date(n.updated_at).toLocaleDateString('en-IN',{month:'short',day:'numeric'}).toUpperCase()}</small></article>`).join(''):empty('Your ideas have a home','Start with a thought, a sketch in words, or a plan for later.')}</div>`;}
function safeHttps(value){try{const u=new URL(value);return u.protocol==='https:'?u.href:'';}catch{return '';}}
function portfolioPage(){let items=state.portfolio.filter(n=>`${n.title} ${n.description}`.toLowerCase().includes(state.filter.toLowerCase()));const cards=items.map(n=>{const cover=safeHttps(n.cover_url),repo=safeHttps(n.repository_url),demo=safeHttps(n.demo_url);return `<article class="portfolio-card"><div class="portfolio-cover">${cover?`<img class="portfolio-img" src="${esc(cover)}" alt="" loading="lazy" referrerpolicy="no-referrer"/>`:mark(40)}<span class="portfolio-visibility ${n.is_published?'published':''}">${n.is_published?'Published':'Private'}</span></div><div class="portfolio-body"><div class="project-card-title"><h3>${esc(n.title)}</h3><div class="row-actions"><button class="mini-icon" data-edit="portfolio" data-id="${esc(n.id)}" aria-label="Edit portfolio item">${icon('edit',15)}</button><button class="mini-icon" data-delete="portfolio" data-table="portfolio_items" data-id="${esc(n.id)}" aria-label="Delete portfolio item">${icon('trash',15)}</button></div></div><p>${esc(n.description||'Add a few words about this work.')}</p><small>${esc(n.technologies?.join(' · ')||n.category)}</small>${repo||demo?`<div class="portfolio-links">${repo?`<a href="${esc(repo)}" target="_blank" rel="noopener noreferrer">Repository ${icon('arrow',12)}</a>`:''}${demo?`<a href="${esc(demo)}" target="_blank" rel="noopener noreferrer">Live demo ${icon('arrow',12)}</a>`:''}</div>`:''}</div></article>`;}).join('');return `${pageHeading('WHAT YOU’RE MAKING','Portfolio','Choose what you share. Every new item starts private.','Add work')}<div class="privacy-note">${icon('brief',18)}<div><strong>Your work stays yours.</strong><span>Items are private until you turn on publishing. Published items can be read by anyone through the public data endpoint.</span></div></div><div class="portfolio-grid">${items.length?cards:empty('Show what you’re building','Collect your best work in one place, then decide what you want to share.')}</div>`;}
function analyticsPage(){const completed=state.tasks.filter(t=>t.status==='done').length,open=state.tasks.filter(t=>t.status!=='done').length,proj=state.projects.reduce((o,p)=>(o[p.status]=(o[p.status]||0)+1,o),{});return `${pageHeading('A MOMENT TO REFLECT','Your progress','A view of what you have actually recorded.')}<div class="stat-grid analytics-stats"><article class="stat-card"><span class="stat-icon green">${icon('check')}</span><span class="stat-label">Completed tasks</span><strong>${completed}</strong><small>All time</small></article><article class="stat-card"><span class="stat-icon blue">${icon('check')}</span><span class="stat-label">Open tasks</span><strong>${open}</strong><small>Across your workspace</small></article><article class="stat-card"><span class="stat-icon violet">${icon('layers')}</span><span class="stat-label">Projects</span><strong>${state.projects.length}</strong><small>All statuses</small></article><article class="stat-card"><span class="stat-icon amber">${icon('calendar')}</span><span class="stat-label">Events</span><strong>${state.events.length}</strong><small>On your calendar</small></article></div><div class="content-grid"><section class="panel"><div class="panel-heading"><div><p class="eyebrow">PROJECT MIX</p><h2>By status</h2></div></div>${Object.keys(proj).length?Object.entries(proj).map(([k,v])=>`<div class="analytics-row"><span>${k.replace('_',' ')}</span><div class="progress-track"><i style="width:${Math.round(v/state.projects.length*100)}%"></i></div><b>${v}</b></div>`).join(''):empty('No project data yet','Once you add projects, you’ll see how they are moving.')}</section><section class="panel"><div class="panel-heading"><div><p class="eyebrow">KEEP GOING</p><h2>What this measures</h2></div></div><p class="muted copy">These totals reflect records stored in your workspace. Task completion counts the tasks currently marked complete; it does not estimate effort or compare you with anyone else.</p><div class="analytics-note">${icon('chart',19)} <span>Productivity is personal. Use these numbers as a reflection, not a score.</span></div></section></div>`;}
function settingsPage(){return `${pageHeading('MAKE IT YOURS','Settings','A workspace that fits how you like to work.')}<div class="settings-grid"><section class="panel settings-panel"><div class="panel-heading"><div><p class="eyebrow">YOUR PROFILE</p><h2>Personal details</h2></div></div><form id="profile-form">${field('Display name','display_name',state.profile?.display_name||'')}${field('Email address','email',state.user.email||'','email','disabled')}${selectField('Timezone','timezone',state.profile?.timezone||'Asia/Kolkata',[['Asia/Kolkata','India Standard Time (Kolkata)'],['America/Los_Angeles','Pacific Time'],['America/New_York','Eastern Time'],['Europe/London','London'],['Europe/Berlin','Central Europe'],['Asia/Tokyo','Japan Standard Time'],['Australia/Sydney','Sydney']])}<button class="btn primary" type="submit">Save profile</button></form></section><section class="panel settings-panel"><div class="panel-heading"><div><p class="eyebrow">MAKE IT FEEL RIGHT</p><h2>Appearance</h2></div></div><p class="muted">Choose a theme for your workspace.</p><div class="theme-options"><button class="theme-option ${document.documentElement.dataset.theme==='dark'?'selected':''}" data-theme-choice="dark"><span class="theme-preview dark-preview">◐</span><strong>Dark</strong><small>Easy on the eyes</small></button><button class="theme-option ${document.documentElement.dataset.theme==='light'?'selected':''}" data-theme-choice="light"><span class="theme-preview light-preview">☼</span><strong>Light</strong><small>Bright and clear</small></button></div><div class="settings-divider"></div><div class="account-row"><div><strong>Sign out</strong><small>Sign out of this device.</small></div><button class="btn ghost" id="settings-signout">${icon('logout',16)} Sign out</button></div></section></div><section class="privacy-note settings-privacy">${icon('settings',18)}<div><strong>Your data, your workspace.</strong><span>Projects, tasks, calendar events, and notes are private to your account. Portfolio entries become publicly readable only when you explicitly publish them.</span></div></section>`;}
function closeModal(){document.querySelector('#modal-root').innerHTML='';}
function createModal(type,date){editModal(type,null,date);}
function editModal(type,id,date){const table={project:'projects',task:'tasks',event:'events',note:'notes',portfolio:'portfolio_items'}[type];const source={project:state.projects,task:state.tasks,event:state.events,note:state.notes,portfolio:state.portfolio}[type];const item=id?source.find(x=>x.id===id):{};let body='';
  if(type==='project')body=`${field('Project name','name',item.name||'','text','required maxlength="120"')}${textarea('Description','description',item.description||'')}${selectField('Status','status',item.status||'active',[['active','In progress'],['on_hold','On hold'],['completed','Completed'],['archived','Archived']])}${selectField('Priority','priority',item.priority||'medium',[['low','Low'],['medium','Medium'],['high','High']])}<div class="form-row">${field('Start date','start_date',item.start_date||'','date')}${field('Deadline','deadline',item.deadline||'','date')}</div><label class="field"><span>Project color</span><input name="color" type="color" value="${item.color||'#8b7cf6'}"/></label>`;
  if(type==='task')body=`${field('Task title','title',item.title||'','text','required maxlength="240"')}${textarea('Description','description',item.description||'')}${selectField('Project','project_id',item.project_id||'',[['','Personal task'],...state.projects.map(p=>[p.id,p.name])])}<div class="form-row">${selectField('Priority','priority',item.priority||'medium',[['low','Low'],['medium','Medium'],['high','High']])}${selectField('Status','status',item.status||'todo',[['todo','To do'],['in_progress','In progress'],['done','Completed']])}</div>${field('Due date','due_date',item.due_date||'','date')}`;
  if(type==='event'){let start=item.start_at?new Date(item.start_at):date?wallTimeToUtc(date+'T10:00',zone()):new Date(Date.now()+3600000),end=item.end_at?new Date(item.end_at):new Date(start.getTime()+3600000);const local=d=>localInputAt(d,zone());body=`${field('Event title','title',item.title||'','text','required maxlength="180"')}${textarea('Description','description',item.description||'')}<div class="form-row">${field('Starts','start_at',local(start),'datetime-local','required')}${field('Ends','end_at',local(end),'datetime-local','required')}</div><label class="check-field"><input type="checkbox" name="all_day" ${item.all_day?'checked':''}/> All day</label><label class="field"><span>Event color</span><input name="color" type="color" value="${item.color||'#8b7cf6'}"/></label>`;}
  if(type==='note')body=`${field('Title','title',item.title||'','text','required maxlength="180"')}${textarea('Your thoughts','body',item.body||'')}${selectField('Project','project_id',item.project_id||'',[['','No project'],...state.projects.map(p=>[p.id,p.name])])}<p class="form-hint">Your note is private and saves when you choose Save note.</p>`;
  if(type==='portfolio')body=`${field('Work title','title',item.title||'','text','required maxlength="140"')}${textarea('Description','description',item.description||'')}${field('Cover image URL (HTTPS)','cover_url',item.cover_url||'','url','placeholder="https://…"')}${field('Technologies (comma separated)','technologies',item.technologies?.join(', ')||'')}${field('Category','category',item.category||'Project')}${field('Repository URL (HTTPS)','repository_url',item.repository_url||'','url')}${field('Live demo URL (HTTPS)','demo_url',item.demo_url||'','url')}<label class="check-field"><input type="checkbox" name="is_published" ${item.is_published?'checked':''}/> Publish this item publicly</label><p class="form-hint">Published items can be read publicly via the portfolio data endpoint. A public portfolio page is not included yet.</p>`;
  document.querySelector('#modal-root').innerHTML=modal(`${id?'Edit':'New'} ${type}`,body,type==='note'?'Save note':'Save');document.querySelector('#modal-form').dataset.kind=type;document.querySelector('#modal-form').dataset.id=id||'';}
async function submitModal(e){e.preventDefault();const form=e.currentTarget,type=form.dataset.kind,id=form.dataset.id||null,d=Object.fromEntries(new FormData(form));const button=form.querySelector('button[type=submit]');button.disabled=true;button.textContent='Saving…';try{let payload;
  if(type==='project')payload={...d,name:d.name.trim(),start_date:d.start_date||null,deadline:d.deadline||null};
  if(type==='task')payload={...d,title:d.title.trim(),project_id:d.project_id||null,due_date:d.due_date||null};
  if(type==='event'){const allDay=form.elements.all_day.checked;let start,end;if(allDay){const day=d.start_at.slice(0,10),next=new Date(day+'T12:00:00');next.setDate(next.getDate()+1);const nextKey=`${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}-${String(next.getDate()).padStart(2,'0')}`;start=wallTimeToUtc(day+'T00:00',zone());end=wallTimeToUtc(nextKey+'T00:00',zone());}else{start=wallTimeToUtc(d.start_at,zone());end=wallTimeToUtc(d.end_at,zone());}if(!isValidEventRange(start,end))throw new Error('The end time must be after the start time.');payload={...d,start_at:start.toISOString(),end_at:end.toISOString(),all_day:allDay,color:d.color};}
  if(type==='note')payload={...d,title:d.title.trim(),project_id:d.project_id||null};
  if(type==='portfolio'){for(const k of ['cover_url','repository_url','demo_url'])if(d[k]&&!d[k].startsWith('https://'))throw new Error(`${k.replace('_url','')} must use HTTPS.`);payload={...d,title:d.title.trim(),technologies:d.technologies.split(',').map(x=>x.trim()).filter(Boolean),is_published:form.elements.is_published.checked};}
  await save(({project:'projects',task:'tasks',event:'events',note:'notes',portfolio:'portfolio_items'})[type],payload,id);closeModal();toast(`${type[0].toUpperCase()+type.slice(1)} saved.`);
 }catch(err){toast(err.message||'Save failed. Your changes are still in the form.','error');button.disabled=false;button.textContent='Try again';}}
async function toggleTask(id){const item=state.tasks.find(t=>t.id===id);try{await save('tasks',{status:item.status==='done'?'todo':'done'},id);toast(item.status==='done'?'Task reopened.':'Task completed.');}catch(err){toast(err.message,'error');}}
function toggleTheme(){setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');}
async function setTheme(theme){document.documentElement.dataset.theme=theme;if(state.profile){try{const {error}=await db.from('profiles').update({theme}).eq('id',state.user.id);if(error)throw error;state.profile.theme=theme;render();}catch(e){toast(e.message,'error');}}else render();}
async function boot(){if(!ready){app.innerHTML=`<main class="config-page"><div class="config-card">${mark(46)}<p class="eyebrow">DEVVERSE STUDIO</p><h1>Almost ready to build.</h1><p>The frontend is connected to the intended Supabase project. Add its publishable key in <code>public/config.js</code> after the project finishes starting, then apply the included database migration.</p><div class="config-url">${esc(cfg.supabaseUrl||'Supabase project URL not set')}</div><p class="muted">The publishable key is meant for browser apps. Never use a service-role key here.</p></div></main>`;return;}if(location.search.includes('recovery=1'))state.authMode='recover-password';const {data:{session}}=await db.auth.getSession();state.user=session?.user||null;if(state.user&&state.authMode==='recover-password')showAuth();else if(state.user)await loadData();else showLanding();db.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){state.authMode='recover-password';state.user=session?.user||null;showAuth();return;}state.user=session?.user||null;if(state.user&&state.authMode!=='recover-password')loadData();else if(!state.user&&state.authMode!=='recover-password'){clearWorkspaceData();showLanding();}});}
document.addEventListener('click',e=>{const page=e.target.closest('[data-page]');if(page){state.page=page.dataset.page;render();}if(e.target.id==='today-btn'){state.month=new Date(today.getFullYear(),today.getMonth(),1);render();}if(e.target.id==='settings-signout')db.auth.signOut();if(e.target.dataset.themeChoice)setTheme(e.target.dataset.themeChoice);});
document.addEventListener('submit',async e=>{if(e.target.id==='profile-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{const {error}=await db.from('profiles').upsert({id:state.user.id,display_name:d.display_name.trim(),timezone:d.timezone,theme:state.profile?.theme||'dark'});if(error)throw error;state.profile={...state.profile,...d};toast('Profile saved.');render();}catch(err){toast(err.message,'error');}}});
boot();
